{
  "title": "The Glass Diver's Rescue",
  "gate_token": "ZBXtaqHzJVMITxS4A2HyFg",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara studies a torn map at the city's edge.",
      "visual_description": "A ruined gate archway overgrown with vines, dust swirling in the light as Mara traces ink lines with her finger.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The Glass Diver swims through a shattered window into the street.",
      "visual_description": "A window pane ripples like water; the diver emerges helmet-first, coat reflecting broken glass and distant torches.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "The Oracle Lamp flickers a warning from a stone alcove.",
      "visual_description": "An oily flame inside an old lamp sputters, one glowing eye forming in the fire as shadows stretch.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "Mara and the diver meet beneath a tattered royal banner.",
      "visual_description": "Faded cloth snaps in the wind above a cracked courtyard, Mara pointing at a compass while the diver adjusts his helmet.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The Tin Fox scampers ahead, key-wind tail clicking.",
      "visual_description": "A small metal fox with blue glass eyes darts over rubble, its tail spinning as it sniffs the air.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The party finds a cursed tower with a locked door.",
      "visual_description": "A spiral tower of black stone, its iron door etched with runes that pulse faintly; Mara consults her map.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "The Oracle Lamp reveals a hidden trap beside the tower.",
      "visual_description": "The lamp's flame casts a sharp glow on a pressure plate and a thin wire stretching across the doorway.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "The Sleeping Tax Collector snores behind a ledger desk inside the tower.",
      "visual_description": "A dim chamber with stacks of stamped papers; a man in ink-stained sleeves sleeps with his head on a ledger.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 9,
      "caption": "Mara shakes the tax collector awake for a key.",
      "visual_description": "Mara leans over the desk, tapping a compass on the wood; the collector stirs, papers stuck to his sleeve.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 10,
      "caption": "The tax collector mutters and hands over a rusted key.",
      "visual_description": "He fumbles in a drawer and drops a heavy iron key onto the desk, then goes back to sleep.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "The party unlocks a magic door that whispers riddles.",
      "visual_description": "The door's wood surface ripples like water, a whispering voice emerging from the grain; the Glass Diver touches it.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "The Oracle Lamp answers the door's riddle.",
      "visual_description": "The lamp's flame brightens, its eye pupil narrowing as it speaks; the door shudders and swings open.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "They find the rescued captive in an upper chamber.",
      "visual_description": "A small room with shattered glass on the floor, a figure huddled in a corner; the diver extends a hand.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "Armored patrols march through the courtyard below.",
      "visual_description": "Through a broken window, metal footsteps echo as rows of faceless armor clank across the flagstones.",
      "characters": ["oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The party races down a spiral staircase.",
      "visual_description": "Dust and loose stones tumble as the group descends a narrow stair, the lamp swinging wildly.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "They cross a stone bridge over a dry moat.",
      "visual_description": "A long bridge with cracked parapets, moonlight illuminating the distance; the party runs, the tax collector stumbling.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The bridge begins to crumble behind them.",
      "visual_description": "Stones fall into the dark moat as the bridge cracks; the Glass Diver looks back as the patrols stop at the gap.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "The survivors reach the outer gate and the open road.",
      "visual_description": "A broken archway at the city's edge, dawn light spilling through; the party pauses, catching breath, the lamp's flame steady.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

